'use client';

import { useState } from 'react';
import { Icon } from '@/components/icons';
import './workbench.css';

/**
 * The three files that make Node A run in Wokwi, served from this site.
 *
 * They are generated by `npm run sync:wiring` from the firmware and the wiring,
 * into public/workbench/wokwi/node-a/. Each card copies its file, so the reader
 * pastes it into Wokwi's editor without visiting the repository.
 */

const BASE = '/workbench/wokwi/node-a';

const FILES = [
  { name: 'sketch.ino', what: 'The firmware, in one file. Replace everything in Wokwi’s sketch.ino with it.' },
  { name: 'diagram.json', what: 'The parts and the wires. Replace everything in Wokwi’s diagram.json with it.' },
  { name: 'libraries.txt', what: 'The three libraries. Add each name in Wokwi’s Library Manager.' },
] as const;

function FileCard({ name, what }: { name: string; what: string }) {
  const [state, setState] = useState<'idle' | 'copied' | 'failed'>('idle');

  async function copy() {
    try {
      const response = await fetch(`${BASE}/${name}`);
      if (!response.ok) throw new Error(String(response.status));
      await navigator.clipboard.writeText(await response.text());
      setState('copied');
    } catch {
      // No Clipboard API (plain http on a LAN address), or the fetch failed: the link still works.
      setState('failed');
    }
    window.setTimeout(() => setState('idle'), 2000);
  }

  return (
    <li className="wokwi-file">
      <p className="wokwi-file-name">
        <code>{name}</code>
      </p>
      <p className="wokwi-file-what">{what}</p>
      <p className="wokwi-file-actions">
        <button type="button" onClick={copy}>
          <Icon name={state === 'copied' ? 'check' : 'copy'} size={14} />
          <span aria-live="polite">{state === 'copied' ? 'Copied' : state === 'failed' ? 'Use the link' : 'Copy'}</span>
        </button>
        <a href={`${BASE}/${name}`} target="_blank" rel="noreferrer noopener">
          Open
          <Icon name="external" size={13} />
        </a>
      </p>
    </li>
  );
}

export function WokwiFiles() {
  return (
    <div className="wokwi">
      <ol className="wokwi-steps">
        <li>
          Open a new ESP32 project in Wokwi. No account is needed to run it.
          <a className="btn btn-primary" href="https://wokwi.com/projects/new/esp32" target="_blank" rel="noreferrer noopener">
            New ESP32 project
            <Icon name="external" size={15} />
          </a>
        </li>
        <li>Copy each file below into it.</li>
        <li>Press the green play button. The first build waits in Wokwi’s free queue for a minute or two.</li>
        <li>Click the load cell for its weight slider. Press TARE, add weight, press PHOTO.</li>
      </ol>
      <ul className="wokwi-files">
        {FILES.map((file) => (
          <FileCard key={file.name} {...file} />
        ))}
      </ul>
    </div>
  );
}
